    at CompileMetadataResolver.getNgModuleMetadata (PathRemovedForDemo\node_modules\@angular\compiler\bundles\compiler.umd.js:15445:49)
    at CompileMetadataResolver.getNgModuleSummary (PathRemovedForDemo\node_modules\@angular\compiler\bundles\compiler.umd.js:15358:52)

### Desired functionality.
The ng cli should detect this fault and report the module that causes the call stack exception

### Mention any other details that might be useful.
The issue can be found in **compile.umd.js**:
function: **CompileMetadataResolver.prototype.getNgModuleMetadata **
On the code:

```
 if (meta.exports) {
            flattenAndDedupeArray(meta.exports).forEach(function (exportedType) {
                if (!isValidType(exportedType)) {
                    _this._reportError(syntaxError("Unexpected value '" + stringifyType(exportedType) + "' exported by the module '" + stringifyType(moduleType) + "'"), moduleType);
                    return;
                }
                var /** @type {?} */ exportedModuleSummary = _this.getNgModuleSummary(exportedType);                 if (exportedModuleSummary) {
                    exportedModules.push(exportedModuleSummary);
                }
                else {
                    exportedNonModuleIdentifiers.push(_this._getIdentifierMetadata(exportedType));
                }
            });
        }
```

**var  exportedModuleSummary = _this.getNgModuleSummary(exportedType); 
=> this cause the recursion and endless loop because 'getNgModuleMetadata ' is called again for the same module** 

So my suggestion is watch how deep the recusion is going, and for example start logging warnings when reached 5 nested call.
Something like this:

```
CompileMetadataResolver.prototype.getNgModuleMetadata = function (moduleType, throwIfNotFound, nested = 0) {
        nested++;
        if(nested > 4) console.warn(´nested module {moduleType.name} (level: ${nested})´)
```
of course function calling **getNgModuleMetadata** should be modified to.

Can someone on the core cli team confirm this is a good approach?

Another approach is of course checking for the module name that is calling it self, but suppose you have something like this moduleX=>export moduleY=>exportmoduleX...

If so, I will create a pull request
